PRAGMA foreign_keys=ON;
CREATE TABLE MEMBERS(MemberID TEXT PRIMARY KEY,Name TEXT NOT NULL,Phone TEXT,Points INTEGER DEFAULT 0,JoinDate TEXT);
CREATE TABLE CATEGORIES(CategoryID TEXT PRIMARY KEY,CategoryName TEXT NOT NULL UNIQUE);
CREATE TABLE PRODUCTS(ProductID TEXT PRIMARY KEY,ProductName TEXT NOT NULL,CategoryID TEXT,Price REAL NOT NULL,StockQuantity INTEGER NOT NULL,MinStock INTEGER NOT NULL,FOREIGN KEY(CategoryID) REFERENCES CATEGORIES(CategoryID));
CREATE TABLE ORDERS(OrderID TEXT PRIMARY KEY,MemberID TEXT,OrderDate TEXT,TotalAmount REAL,FOREIGN KEY(MemberID) REFERENCES MEMBERS(MemberID));
CREATE TABLE ORDER_DETAILS(DetailID TEXT PRIMARY KEY,OrderID TEXT,ProductID TEXT,Quantity INTEGER,UnitPrice REAL,FOREIGN KEY(OrderID) REFERENCES ORDERS(OrderID),FOREIGN KEY(ProductID) REFERENCES PRODUCTS(ProductID));
CREATE TABLE INVENTORY_LOG(LogID TEXT PRIMARY KEY,ProductID TEXT,ChangeType TEXT,ChangeQuantity INTEGER,ChangeDate TEXT,FOREIGN KEY(ProductID) REFERENCES PRODUCTS(ProductID));
